import time
import matplotlib.pyplot as plt
from functools import cache # 3.9 and above

@cache
def a(n):

    # Base Case
    if n &lt;= 1:
        return n

    # Recursive Case
    return a(n-1) + a(n-2)

def main():
    time_record = []
    for n in range(1,25):
        tic = time.time()
        a(n)
        toc = time.time()
        time_record.append(toc-tic)

    plt.plot(np.arange(1,25), time_record) 
    plt.show()


if __name__ == "__main__":
    main()
